      code: function (v) { return ["upto is " + v.upto, "i is 1", "i fle upto", "  i%15 ieq 0", "    out prn \"FizzBuzz\"", "  i%3 oeq 0", "    out prn \"Fizz\"", "  i%5 oeq 0", "    out prn \"Buzz\"", "  now oth now", "    out prn i"]; },
